const body = $json.body ?? $json;

function requiredString(value, field) {
  const text = String(value ?? '').trim();
  if (!text) {
    throw new Error(`Campo obrigatorio ausente: ${field}`);
  }
  return text;
}

function optionalString(value) {
  const text = String(value ?? '').trim();
  return text || null;
}

function normalizePhone(value) {
  const digits = String(value ?? '').replace(/\D/g, '');
  if (!digits) {
    throw new Error('Campo obrigatorio ausente: telefone_cliente');
  }
  return digits;
}

function fallbackCode() {
  const now = new Date();
  const stamp = now.toISOString().slice(0, 10).replace(/-/g, '');
  const suffix = Math.random().toString(36).slice(2, 8).toUpperCase();
  return `SOL-${stamp}-${suffix}`;
}

return [{
  json: {
    codigo_externo: optionalString(body.codigo_externo) ?? fallbackCode(),
    origem: optionalString(body.origem) ?? 'whatsapp',
    canal_origem: optionalString(body.canal_origem) ?? 'n8n',
    nome_cliente: requiredString(body.nome_cliente, 'nome_cliente'),
    telefone_cliente: normalizePhone(body.telefone_cliente),
    procedimento_nome: optionalString(body.procedimento_nome) ?? 'Consulta geral',
    dia_desejado: requiredString(body.dia_desejado, 'dia_desejado'),
    horario_desejado: optionalString(body.horario_desejado),
    observacoes_cliente: optionalString(body.observacoes_cliente),
    payload_externo: body.payload_externo ?? body,
    resumo_atendimento: body.resumo_atendimento ?? null
  }
}];

const entrada = $('Normalizar entrada').first().json;
const rpcResponse = $('Upsert paciente por telefone').first().json;

const pacienteId = typeof rpcResponse === 'string'
  ? rpcResponse
  : rpcResponse?.id ?? rpcResponse?.data ?? rpcResponse?.value ?? null;

return [{
  json: {
    ...entrada,
    paciente_id: pacienteId,
    status: 'novo'
  }
}];
